import{_ as a,o,c as r,ae as l}from"./chunks/framework.DBosx3SP.js";const h=JSON.parse('{"title":"Color","description":"","frontmatter":{},"headers":[],"relativePath":"dx/color.md","filePath":"dx/color.md","lastUpdated":1792899449000}'),t={name:"dx/color.md"};function i(n,e,s,c,d,p){return o(),r("div",null,[...e[0]||(e[0]=[l(`<h1 id="color" tabindex="-1">Color <a class="header-anchor" href="#color" aria-label="Permalink to &quot;Color&quot;">​</a></h1><h2 id="difference-between-colorscale-vs-coordinate-scale" tabindex="-1">Difference between ColorScale vs coordinate Scale <a class="header-anchor" href="#difference-between-colorscale-vs-coordinate-scale" aria-label="Permalink to &quot;Difference between ColorScale vs coordinate Scale&quot;">​</a></h2><p>The coordinate scales are managed as the properties of Plot. Cartesian2 has x-scale and y-scale.<br> However color scales are managed per geometry. Each Geometry can have its own ColorScale.<br> This makes it hard to provide a simple API - that supplies the default color mapping.</p><h2 id="mapping-data-to-colors" tabindex="-1">Mapping data to colors <a class="header-anchor" href="#mapping-data-to-colors" aria-label="Permalink to &quot;Mapping data to colors&quot;">​</a></h2><p>Echarts and ggplot2 support the following four patterns:</p><ul><li>continuous input to discrete colors by uniform binning</li><li>continuous input to discrete colors by custom binning boundaries</li><li>continuous input to continuous colors defined by linear interpolation of a few colors ([c1, c2, c3] -&gt; 0.0=c1, 0.5=c2, 1.0=c3)</li><li>discrete input to discrete colors by lookup</li></ul><h2 id="gradient-fill" tabindex="-1">Gradient Fill <a class="header-anchor" href="#gradient-fill" aria-label="Permalink to &quot;Gradient Fill&quot;">​</a></h2><ul><li>linear gradient (start point, start color, end point, end color, pad)</li><li>radiant gradient (start point, start radius, end point, end radius, color steps of two or more) <ul><li>SVG supports arbitrary number of stop points (percent and color)</li><li>visual example: <a href="https://learn.microsoft.com/en-us/typography/opentype/spec/colr#radial-gradients" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/typography/opentype/spec/colr#radial-gradients</a></li><li>two-circle model is used by PDF, Cairo, HTML Canvas, R</li></ul></li><li>each gradient can be color scale or global</li></ul><h2 id="color-space" tabindex="-1">Color Space <a class="header-anchor" href="#color-space" aria-label="Permalink to &quot;Color Space&quot;">​</a></h2><ul><li>sRGB for wire / file</li><li>linear RGB for blending: preserve the amount of lights</li><li>OKLAB for gradients: <a href="https://chriscoyier.net/2023/05/25/two-things-that-are-not-great-about-oklch/" target="_blank" rel="noreferrer">https://chriscoyier.net/2023/05/25/two-things-that-are-not-great-about-oklch/</a></li><li>OKLCH for hue sweep to avoid low-chroma region</li></ul><h2 id="color-attribute" tabindex="-1">Color Attribute <a class="header-anchor" href="#color-attribute" aria-label="Permalink to &quot;Color Attribute&quot;">​</a></h2><ul><li>const color</li><li>color series (dataframe column name)</li><li>global linear gradient</li><li>global radial gradient</li><li>local linear gradient (local = gradient start resets each item)</li><li>local radial gradient</li><li>color scale (map data to colors) -&gt; project before passing input to shader</li></ul><p>Fill pattern -&gt; use texture as it&#39;s zoom invariant</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><ul><li>Palette: a finite collection of colors.</li><li>Ramp: an immutable continuous function from normalized position to color, such as Viridis.</li><li>ColorScale: maps a data domain to colors using a palette or ramp.</li><li>ColorSeries: a graph-bound packed-sRGBA column, logically distinct from raw U32 codes.</li><li><code>Array::color</code>: the graph-free packed-sRGBA column form used in a DataFrame.</li></ul><h2 id="color-format-flow" tabindex="-1">Color Format Flow <a class="header-anchor" href="#color-format-flow" aria-label="Permalink to &quot;Color Format Flow&quot;">​</a></h2><pre><code>            sRGB vs linear   |  straight vs premultiplied
</code></pre><p>Theme color: sRGB straight<br> Color attr: sRGB straight</p><p>color scalar is manually converted to linear + premultiplied.<br> color attachment is converted to linear (manually in shader) and premultiplied (manually in shader)</p><p>Shader data: linear | premultiplied<br> Shader output: linear | premultiplied<br> wgpu Result: sRGB | premultiplied<br> our CPU conversion: sRGB | straight</p><p>png sRGB | straight<br> native surface sRGB | premultiplied<br> web sRGB | premultiplied</p>`,21)])])}const m=a(t,[["render",i]]);export{h as __pageData,m as default};
